(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.018 + t * 0.25) * 18 + Math.cos(y * 0.013 - t * 0.18) * 12;
  const w1y = Math.cos(y * 0.02 - t * 0.22) * 16 + Math.sin(x * 0.015 + t * 0.3) * 11;
  const w2x = Math.sin((x + w1x) * 0.025 + t * 0.15) * 8;
  const w2y = Math.cos((y + w1y) * 0.03 - t * 0.12) * 7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 75+Math.cos(t*0.35)*55, 0.075, 2.1, 0.9],
    [325+Math.cos(t*0.45)*105, 165+Math.sin(t*0.6)*55, 0.09, 1.8, 1.1],
    [240+Math.sin(t*0.28+2)*150, 115+Math.cos(t*0.42+1)*95, 0.055, 2.4, 0.8],
    [115+Math.cos(t*0.7+1)*85, 185+Math.sin(t*0.55+3)*65, 0.11, 1.6, 1.0],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 0.85],
    [240+Math.cos(t*0.32+5)*130, 205+Math.sin(t*0.5)*85, 0.085, 2.0, 1.05],
    [80+Math.sin(t*0.6+3)*70, 50+Math.cos(t*0.4+1)*60, 0.1, 1.4, 0.95],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+4)*50, 0.07, 2.2, 0.9]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * wt;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.7) * wt;
    wS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.1) * wt * 0.5;
  }
  const tw = src.reduce((s, r) => s + r[4], 0);
  const act = aS/tw, inh = iS/tw, wav = wS/tw;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.2)*0.25;
  const bg4 = Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const bg5 = Math.sin(sx*0.06+sy*0.08-t*1.4)*0.15;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.2)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.25 + spiral + wav*0.15)*2.0);
  const cellA = Math.sin(sx*0.14)*Math.sin(sy*0.14);
  const cellB = Math.sin((sx+sy)*0.09+t*0.8)*0.5;
  const cellC = Math.sin(sx*0.22-t*0.5)*Math.cos(sy*0.18+t*0.3)*0.3;
  const cell = Math.tanh((cellA+cellB+cellC)*1.4)*0.25;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend = reaction*0.65 + cell*0.25 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,42,82],[14,78,105],[18,118,118],
    [35,155,130],[120,185,100],[195,195,65],
    [215,155,55],[210,110,60],[175,60,65],
    [120,35,70],[70,22,58],[30,15,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const r0 = pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g0 = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b0 = pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum = 0.82 + Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65 ? 1.12 : (Math.abs(reaction)<0.15 ? 0.88 : 1.0);
  const contour = Math.abs(blend - Math.round(blend*8)/8) < 0.025 ? 0.7 : 1.0;
  const vign = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)*0.0008;
  const m = Math.min(255, (r0*lum*edge*contour*vign))|0;
  const n = Math.min(255, (g0*lum*edge*contour*vign))|0;
  const p = Math.min(255, (b0*lum*edge*contour*vign))|0;
  return [Math.max(0,m), Math.max(0,n), Math.max(0,p)];
}
